import { withPluginApi } from "discourse/lib/plugin-api";
import I18n from "discourse-i18n";

export default {
  name: "disco-toc-composer",

  initialize() {
    withPluginApi((api) => {
      const currentUser = api.getCurrentUser();
      if (!currentUser) {
        return;
      }

      const minimumTL = settings.minimum_trust_level_to_create_TOC;

      if (currentUser.trust_level >= minimumTL || currentUser.staff) {
        if (!I18n.translations[I18n.currentLocale()].js.composer) {
          I18n.translations[I18n.currentLocale()].js.composer = {};
        }
        I18n.translations[I18n.currentLocale()].js.composer.contains_dtoc = " ";

        api.addComposerToolbarPopupMenuOption({
          action: (toolbarEvent) => {
            toolbarEvent.applySurround(
              `<div data-theme-toc="true">`,
              `</div>`,
              "contains_dtoc"
            );
          },
          icon: "align-left",
          label: themePrefix("insert_table_of_contents"),
          condition: (composer) => {
            return (
              settings.enable_TOC_for_replies || composer.model.topicFirstPost
            );
          },
        });

        if (settings.enable_TOC_for_replies) {
          document.body.classList.add("toc-for-replies-enabled");
        }
      }
    });
  },
};

{
  "name": "DiscoTOC",
  "component": true,
  "about_url": "https://meta.discourse.org/t/discotoc-automatic-table-of-contents/111143",
  "license_url": "https://github.com/discourse/DiscoTOC/blob/main/LICENSE",
  "theme_version": "2.1.0",
  "assets": {
    "icons-sprite": "/assets/sprite.svg"
  },
  "modifiers": {
    "svg_icons": ["hashtag"]
  }
}

{
  "extends": "discourse/tsconfig-plugin",
  "include": [
    "javascripts/**/*",
    "migrations/**/*",
    "test/**/*",
    "node_modules/discourse/declarations/**/*"
  ],
  "compilerOptions": {
    "paths": {
      "admin/*": ["./node_modules/discourse/declarations/admin/*"],
      "float-kit/*": ["./node_modules/discourse/declarations/float-kit/*"],
      "select-kit/*": ["./node_modules/discourse/declarations/select-kit/*"],
      "truth-helpers": [
        "./node_modules/discourse/declarations/truth-helpers/index.d.ts"
      ],
      "truth-helpers/*": [
        "./node_modules/discourse/declarations/truth-helpers/*"
      ]
    }
  }
}
